package com.koios.client.arpg;
import java.util.*;import java.util.function.ToIntFunction;
/** Pixel-width wrapping of system chat, retaining color/style tags across visual lines. */
public final class ChatWrap {
 public static List<String> lines(String text,int maximum,ToIntFunction<String> measure){List<String> out=new ArrayList<>();if(text==null)return out;maximum=Math.max(16,maximum);text=text.replace("<br>","\n");StringBuilder line=new StringBuilder();int prefix=0;for(int i=0;i<text.length();){int begin=i;char c=text.charAt(i);String unit;if(c=='<'){int end=text.indexOf('>',i);if(end>=0){unit=text.substring(i,end+1);i=end+1;}else{unit="<";i++;}}else if(c=='@'&&i+4<text.length()&&text.charAt(i+4)=='@'){unit=text.substring(i,i+5);i+=5;}else{unit=String.valueOf(c);i++;}if(c=='\n'){String value=line.toString().trim();out.add(value);String carry=carry(value);line=new StringBuilder(carry);prefix=carry.length();continue;}if(Character.isWhitespace(c)){if(line.length()==prefix||line.charAt(line.length()-1)==' ')continue;unit=" ";}int last=line.length();line.append(unit);if(measure.applyAsInt(line.toString())<=maximum)continue;int split=line.lastIndexOf(" ");if(split<=prefix)split=last;if(split<=prefix)continue;String value=line.substring(0,split).trim(),rest=line.substring(split).trim();out.add(value);String carry=carry(value);line=new StringBuilder(carry).append(rest);prefix=carry.length();}if(line.length()>prefix||out.isEmpty())out.add(line.toString().trim());return out;}
 private static String carry(String text){LinkedHashMap<String,String> tags=new LinkedHashMap<>();for(int i=0;i<text.length();i++){if(text.charAt(i)=='<'){int end=text.indexOf('>',i);if(end<0)break;String tag=text.substring(i+1,end),name=tag.split("=",2)[0];if(name.startsWith("/"))tags.remove(name.substring(1));else if(name.equals("col")||name.equals("shad")||name.equals("u")||name.equals("str"))tags.put(name,"<"+tag+">");i=end;}else if(text.charAt(i)=='@'&&i+4<text.length()&&text.charAt(i+4)=='@'){tags.put("col",text.substring(i,i+5));i+=4;}}StringBuilder out=new StringBuilder();for(String tag:tags.values())out.append(tag);return out.toString();}
}
